const recentGameChannelCards = `-- name: RecentGameChannelCards :many
WITH picked AS MATERIALIZED (
 SELECT g.id, g.public_id, g.slug, g.first_published_at, g.intake_display_source FROM game_channel_public g WHERE
 ($5::text='' OR EXISTS (
  SELECT 1 FROM game_sources s WHERE s.game_id=g.id AND s.platform_code=$5 AND s.active))
 AND (g.first_published_at IS NULL OR g.first_published_at<=$6::timestamptz)
 AND (NOT $7::boolean OR
  (g.first_published_at IS NULL AND $8::integer=0)
  OR (g.first_published_at=$9::timestamptz AND g.public_id>$10::text)
  OR g.first_published_at<$9::timestamptz
  OR (g.first_published_at IS NULL AND $8=1 AND g.public_id>$10))
 ORDER BY g.first_published_at DESC NULLS LAST,g.public_id LIMIT $11::integer
)
SELECT game_channel_card(g.id,g.public_id,g.slug,g.first_published_at,
 game_presentation(g.id,g.intake_display_source)->'localizations',f.genres,f.systems,f.release_state,f.release,
 game_channel_cover(g.id,g.intake_display_source,$1::text,$2::text,$3::text),
 (SELECT q.price FROM game_channel_quotes($2,$4::text,$3) q(game_id,game_source_id,locale,confirmed_at,price)
  WHERE q.game_id=g.id ORDER BY (q.game_source_id=g.intake_display_source) DESC NULLS LAST,
   (q.locale=$1) DESC,q.confirmed_at DESC,q.game_source_id LIMIT 1))::jsonb AS card,
 (g.first_published_at IS NULL)::integer AS e_bucket,
 (-coalesce((extract(epoch FROM g.first_published_at)*1000000)::bigint,0))::bigint AS e_ordering,
 ''::text AS e_name_key,g.public_id
FROM picked g CROSS JOIN LATERAL game_channel_facts(g.id,g.intake_display_source,$1,$2,$3)
 f(genres,systems,developers,release_state,release_day,release)
ORDER BY g.first_published_at DESC NULLS LAST,g.public_id
`

type RecentGameChannelCardsParams struct {
	Language    string             `json:"language"`
	Country     string             `json:"country"`
	Egress      string             `json:"egress"`
	Currency    string             `json:"currency"`
	StoreFilter string             `json:"store_filter"`
	AsOf        pgtype.Timestamptz `json:"as_of"`
	HasAfter    bool               `json:"has_after"`
	AfterBucket int32              `json:"after_bucket"`
	AfterTime   pgtype.Timestamptz `json:"after_time"`
	AfterID     string             `json:"after_id"`
	TakeRows    int32              `json:"take_rows"`
}

type RecentGameChannelCardsRow struct {
	Card      []byte `json:"card"`
	EBucket   int32  `json:"e_bucket"`
	EOrdering int64  `json:"e_ordering"`
	ENameKey  string `json:"e_name_key"`
	PublicID  string `json:"public_id"`
}

func (q *Queries) RecentGameChannelCards(ctx context.Context, arg RecentGameChannelCardsParams) ([]RecentGameChannelCardsRow, error) {
	rows, err := q.db.Query(ctx, recentGameChannelCards,
		arg.Language,
		arg.Country,
		arg.Egress,
		arg.Currency,
		arg.StoreFilter,
		arg.AsOf,
		arg.HasAfter,
		arg.AfterBucket,
		arg.AfterTime,
		arg.AfterID,
		arg.TakeRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RecentGameChannelCardsRow{}
	for rows.Next() {
		var i RecentGameChannelCardsRow
		if err := rows.Scan(
			&i.Card,
			&i.EBucket,
			&i.EOrdering,
			&i.ENameKey,
			&i.PublicID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const saveGameCollectionMembers = `-- name: SaveGameCollectionMembers :execrows
INSERT INTO game_collection_members (collection_id,game_id,position)
SELECT $1::uuid,g.id,m.position::integer
FROM unnest($2::text[]) WITH ORDINALITY m(public_id,position) JOIN games g ON g.public_id=m.public_id
`

type SaveGameCollectionMembersParams struct {
	CollectionID uuid.UUID `json:"collection_id"`
	PublicIds    []string  `json:"public_ids"`
}

func (q *Queries) SaveGameCollectionMembers(ctx context.Context, arg SaveGameCollectionMembersParams) (int64, error) {
	result, err := q.db.Exec(ctx, saveGameCollectionMembers, arg.CollectionID, arg.PublicIds)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

